import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class UnionFindTour {
    static int[] parent, rank;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);   // path compression
        return parent[x];
    }

    static boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;                         // already connected
        if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;                                    // shorter tree under the taller one
        if (rank[ra] == rank[rb]) rank[ra]++;
        return true;
    }

    public static void main(String[] args) {
        String[] people = {"ana", "ben", "cai", "dee", "eli", "fay", "gus", "hal"};
        int n = people.length;
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int[][] friendships = {{0, 1}, {2, 3}, {1, 4}, {5, 6}, {3, 7}, {4, 0}};
        for (int[] f : friendships) {
            boolean merged = union(f[0], f[1]);
            System.out.println(people[f[0]] + " + " + people[f[1]] + (merged ? ": groups merged" : ": already in one group"));
        }
        Map<Integer, List<String>> groups = new TreeMap<>();
        for (int i = 0; i < n; i++) groups.computeIfAbsent(find(i), k -> new ArrayList<>()).add(people[i]);
        System.out.println(groups.size() + " friend groups: " + groups.values());
        System.out.println("ana and eli connected? " + (find(0) == find(4)) + ", ana and hal? " + (find(0) == find(7)));
    }
}

