import java.util.Arrays;

public class UnionByRank {
    static int[] parent, rank;

    static int find(int x) {                       // no path compression here
        while (parent[x] != x) x = parent[x];
        return x;
    }

    static void unionNaive(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra != rb) parent[ra] = rb;             // always the first root under the second
    }

    static void unionByRank(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else {
            parent[rb] = ra;                       // equal ranks: pick one, its rank grows
            rank[ra]++;
        }
    }

    static int height() {
        int best = 0;
        for (int x = 0; x < parent.length; x++) {
            int h = 0;
            for (int y = x; parent[y] != y; y = parent[y]) h++;
            best = Math.max(best, h);
        }
        return best;
    }

    static void reset(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
    }

    public static void main(String[] args) {
        int n = 8;
        reset(n);
        for (int i = 0; i < n - 1; i++) unionNaive(i, i + 1);
        System.out.println("naive:   parent " + Arrays.toString(parent) + ", height " + height());

        reset(n);
        for (int i = 0; i < n - 1; i++) unionByRank(i, i + 1);
        System.out.println("by rank: parent " + Arrays.toString(parent) + ", height " + height());
        System.out.println("         rank   " + Arrays.toString(rank));

        reset(n);
        int[][] pairs = {{0, 1}, {2, 3}, {4, 5}, {6, 7}, {0, 2}, {4, 6}, {0, 4}};   // equal-rank merges
        for (int[] p : pairs) {
            unionByRank(p[0], p[1]);
            System.out.println("union(" + p[0] + "," + p[1] + "): parent " + Arrays.toString(parent) + " rank " + Arrays.toString(rank));
        }
        System.out.println("worst case for 8 elements: height " + height() + " = log2(8)");
    }
}

import java.util.Arrays;

public class PathCompression {
    static int[] parent;
    static int steps;

    static int findCompress(int x) {
        if (parent[x] != x) {
            steps++;                                                // one step up the tree
            parent[x] = findCompress(parent[x]);                    // re-point to the root on the way back
        }
        return parent[x];
    }

    static int findIterative(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];          // pass 1: find the root
        while (parent[x] != root) {                                 // pass 2: re-point the path
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    public static void main(String[] args) {
        int n = 8;
        parent = new int[n];
        for (int i = 0; i < n - 1; i++) parent[i] = i + 1;          // chain 0 -> 1 -> ... -> 7
        parent[n - 1] = n - 1;
        System.out.println("before:       parent " + Arrays.toString(parent));
        steps = 0;
        int root = findCompress(0);
        System.out.println("find(0) = " + root + " took " + steps + " steps");
        System.out.println("after:        parent " + Arrays.toString(parent));
        steps = 0;
        findCompress(0);
        System.out.println("find(0) again took " + steps + " step(s) to reach the root");

        for (int i = 0; i < n - 1; i++) parent[i] = i + 1;          // rebuild the chain
        findIterative(2);
        System.out.println("iterative find(2): parent " + Arrays.toString(parent) + " (0 and 1 were not on the path)");
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class ConnectedComponents {
    static int[] parent, size;
    static int components;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;                       // already one component: count unchanged
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;                            // smaller set joins the larger one
        size[ra] += size[rb];
        components--;
    }

    public static void main(String[] args) {
        int n = 10;
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        components = n;

        int[][] edges = {{0, 1}, {2, 3}, {1, 2}, {4, 5}, {3, 0}, {6, 7}, {8, 6}};
        System.out.println("start: " + components + " components");
        for (int[] e : edges) {
            union(e[0], e[1]);
            System.out.println("edge " + e[0] + "-" + e[1] + ": " + components + " components");
        }

        Map<Integer, List<Integer>> byRoot = new TreeMap<>();
        for (int v = 0; v < n; v++) byRoot.computeIfAbsent(find(v), k -> new ArrayList<>()).add(v);
        List<List<Integer>> groups = new ArrayList<>(byRoot.values());
        groups.sort((a, b) -> Integer.compare(a.get(0), b.get(0)));   // order by smallest member
        for (List<Integer> g : groups) System.out.println("  component " + g + " size " + size[find(g.get(0))]);
        System.out.println("connected(1, 3)? " + (find(1) == find(3)) + ", connected(5, 9)? " + (find(5) == find(9)));
    }
}

public class CycleDetectionUnionFind {
    static int[] parent;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void check(String name, int n, int[][] edges) {
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        System.out.println(name + ":");
        for (int[] e : edges) {
            int ru = find(e[0]), rv = find(e[1]);
            if (ru == rv) {                              // already connected: this edge closes a cycle
                System.out.println("  edge " + e[0] + "-" + e[1] + " closes a cycle");
                return;
            }
            parent[ru] = rv;
            System.out.println("  edge " + e[0] + "-" + e[1] + " joins two components");
        }
        System.out.println("  no cycle: " + n + " vertices, " + edges.length + " edges" + (edges.length == n - 1 ? " -> a tree" : ""));
    }

    public static void main(String[] args) {
        check("tree", 5, new int[][]{{0, 1}, {0, 2}, {2, 3}, {2, 4}});
        check("with a redundant edge", 5, new int[][]{{0, 1}, {1, 2}, {2, 3}, {3, 0}, {3, 4}});
    }
}

